    memset(key_block, 0, 64);
    if (keylen > 64) {
        sha256(key, keylen, key_block);
    } else {
        memcpy(key_block, key, keylen);
    }

    for (int i = 0; i < 64; i++) {
        ipad[i] = key_block[i] ^ 0x36;
        opad[i] = key_block[i] ^ 0x5c;
    }

    sha256_init(&ctx);
    sha256_update(&ctx, ipad, 64);
    sha256_update(&ctx, data, datalen);
    sha256_final(&ctx, inner_hash);

    sha256_init(&ctx);
    sha256_update(&ctx, opad, 64);
    sha256_update(&ctx, inner_hash, 32);
    sha256_final(&ctx, output);

    memset(key_block, 0, 64);
    memset(ipad, 0, 64);
    memset(opad, 0, 64);
    memset(inner_hash, 0, 32);
}

// PBKDF2-HMAC-SHA256
static void pbkdf2_sha256(const uint8_t *password, size_t passlen, const uint8_t *salt, size_t saltlen,
                          uint32_t iterations, uint8_t *output, size_t outputlen) {
    uint32_t blocks = (outputlen + 31) / 32;
    uint8_t U[32], T[32];
    uint8_t salt_block[256];
    uint8_t counter[4];

    for (uint32_t i = 1; i <= blocks; i++) {
        counter[0] = (i >> 24) & 0xff;
        counter[1] = (i >> 16) & 0xff;
        counter[2] = (i >> 8) & 0xff;
        counter[3] = i & 0xff;

        memcpy(salt_block, salt, saltlen);
        memcpy(salt_block + saltlen, counter, 4);

        hmac_sha256(password, passlen, salt_block, saltlen + 4, U);
        memcpy(T, U, 32);

        for (uint32_t j = 1; j < iterations; j++) {
            hmac_sha256(password, passlen, U, 32, U);
            for (int k = 0; k < 32; k++) {
                T[k] ^= U[k];
            }
        }

        size_t offset = (i - 1) * 32;
        size_t copy_len = (outputlen - offset < 32) ? (outputlen - offset) : 32;
        memcpy(output + offset, T, copy_len);

        memset(U, 0, 32);
        memset(T, 0, 32);
    }
    memset(salt_block, 0, sizeof(salt_block));
}

// Secure random bytes
static bool get_random_bytes(uint8_t *buf, size_t len) {
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) return false;
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n <= 0) {
            close(fd);
            return false;
        }
        total += n;
    }
    close(fd);
    return true;
}

// Constant-time comparison
static bool constant_time_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

// Secure memory wipe
static void secure_wipe(void *ptr, size_t len) {
    volatile uint8_t *p = (volatile uint8_t *)ptr;
    while (len--) {
        *p++ = 0;
    }
}

// Hash password with salt
static void hash_password(const char *password, const uint8_t *salt, uint8_t *hash) {
    pbkdf2_sha256((const uint8_t *)password, strlen(password), salt, SALT_LEN, ITERATIONS, hash, HASH_LEN);
}

// Initialize database
static void db_init(UserDatabase *db) {
    memset(db, 0, sizeof(UserDatabase));
}

// Find user by username
static User* db_find_user(UserDatabase *db, const char *username) {
    for (size_t i = 0; i < db->count; i++) {
        if (db->users[i].active && strcmp(db->users[i].username, username) == 0) {
            return &db->users[i];
        }
    }
    return NULL;
}

// Register new user
static bool register_user(UserDatabase *db, const char *username, const char *password) {
    if (db->count >= MAX_USERS) return false;
    if (strlen(username) == 0 || strlen(username) > MAX_USERNAME_LEN) return false;
    if (strlen(password) == 0 || strlen(password) > MAX_PASSWORD_LEN) return false;
    if (db_find_user(db, username) != NULL) return false;

    User *user = &db->users[db->count];
    strncpy(user->username, username, MAX_USERNAME_LEN);
    user->username[MAX_USERNAME_LEN] = '\0';

    if (!get_random_bytes(user->salt, SALT_LEN)) {
        return false;
    }

    hash_password(password, user->salt, user->hash);
    user->active = true;
    db->count++;

    return true;
}

